import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Fournisseur } from 'src/app/models/Fournisseur';
import { Medicament } from 'src/app/models/Medicament';
import { FournisseurService } from 'src/app/services/fournisseur.service';

@Component({
  selector: 'app-fournisseur-detail',
  templateUrl: './fournisseur-detail.component.html',
  styleUrls: ['./fournisseur-detail.component.css']
})
export class FournisseurDetailComponent implements OnInit {
  idFournisseur: number | undefined;
  fournisseur: any;  // Update with the actual type of Fournisseur
  medicaments: any[] = [];
  errorMessage: string = '';
  isLoading: boolean = true;

  constructor(
    private route: ActivatedRoute,
    private fournisseurService: FournisseurService
  ) {}

  ngOnInit(): void {
    // Get idFournisseur from the route parameters
    this.idFournisseur = Number(this.route.snapshot.paramMap.get('id'));  // Ensure 'id' is the route parameter name

    if (isNaN(this.idFournisseur)) {
      this.errorMessage = 'Invalid fournisseur ID';
      this.isLoading = false;
      return;
    }

    // Call the backend service to get the medicaments for this fournisseur
    this.fournisseurService.getMedicamentsByFournisseur(this.idFournisseur).subscribe({
      next: (medicaments) => {
        this.medicaments = medicaments;
        if (this.medicaments.length > 0) {
          const fournisseurId = this.medicaments[0].idfournisseur;  // Assuming the medicaments array contains fournisseur information

          // Fetch fournisseur details
          this.fournisseurService.getFournisseurById(fournisseurId).subscribe({
            next: (fournisseurData) => {
              this.fournisseur = fournisseurData;
              this.isLoading = false;
            },
            error: (error) => {
              this.errorMessage = 'Failed to load fournisseur details';
              this.isLoading = false;
            }
          });
        } else {
          this.errorMessage = 'No medicaments found for this fournisseur';
          this.isLoading = false;
        }
      },
      error: (error) => {
        this.errorMessage = 'Failed to load medicaments';
        this.isLoading = false;
      }
    });
  }
}
